package e.e.a;import org.json.*;public final class HistoryMetadataTest {static int checks;static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}public static void main(String[] args)throws Exception{Object local=new Object();HistorySupport.captureLocal(local,new JSONObject().put("posttime",123456789L).put("viewCount",7).put("postedAt","2026-10-01T12:00:00+09:00").put("ownerName","Owner"));check(HistorySupport.watched(local)==123456789L,"local watched time uses the stored timestamp");check(HistorySupport.views(local)==7,"device watch count preserved");check(HistorySupport.posted(local)==HistorySortRules.watched("2026-10-01T12:00:00+09:00"),"posting date is separate from watch date");Object account=new Object();HistorySupport.capture(account,new JSONObject().put("registeredAt","2026-09-01T20:00:00+09:00").put("owner",new JSONObject().put("nickname","Owner")),new JSONObject().put("viewedAt","2026-10-14T00:01:00+09:00").put("views",99));check(HistorySupport.watched(account)==HistorySortRules.watched("2026-10-14T00:01:00+09:00"),"account watched date restored");check(HistorySupport.views(account)==0,"unreliable account watch count omitted");check(HistorySupport.posted(account)<HistorySupport.watched(account),"posting date remains independent");check(ListActions.sortLabels(false).length==14,"account history provides watch dates plus the complete common sort set");check(ListActions.sortLabels(true).length==14,"both history types provide the same full sort set");System.out.println("History metadata: "+checks+" timestamp/count checks passed");}}
